/** Whole disjunction, selection, and equal-input factoring survive settlement and reopen. */
final class ContextDisjunctiveOuterExistential {
    static int checks;static final int WORK=64000000;
    static void require(boolean value,String why){++checks;if(!value)throw new AssertionError(why);}
    static void verdict(ContextUniversalCandidate.Evaluation e,boolean leading,boolean negative,boolean candidateRule,int mode,String rule,String candidate,String fact,List<String> denys){
        boolean safe=mode!=5&&mode!=8;require(e.status==(safe?Status.CONSISTENT:Status.COLLISION),"disjunctive family verdict: "+e.status+" / "+e.reason);
        List<Entry> entries=new ArrayList<>(e.artifact.staged.primary);for(Snapshot f:e.artifact.foreign)entries.addAll(f.primary);Entry whole=entries.stream().filter(v->v.statement.equals(rule)).findFirst().get();require(whole.kind==Kind.CLAUSES&&whole.witnesses()==0&&whole.clauses.size()==1,"one disjunctive clause retains exactly one whole Source");
        if(safe){ContextUniversalFamilyModel.Certificate cert=e.qualification.certificate;require(cert!=null&&e.qualification.collision==null&&cert.cuts.size()==5,"all five cuts modeled");List<ContextUniversalUnitRounds.Receipt> receipts=new ArrayList<>();List<ContextUniversalQuotientModel.Model> models=new ArrayList<>();for(ContextUniversalFamilyModel.Cut c:cert.cuts){require(c.receipt.verified&&c.receipt.input==cert.input&&c.model.ledger==c.receipt.closureStep.input,"exact model/closure/common-frontier bindings");receipts.add(c.receipt);models.add(c.model);}require(ContextUniversalFamilyModel.certify(cert.input,receipts,models,16,65536,WORK).certified,"independent all-admissible-value recertification");heads(e,leading,negative,whole,fact,denys,mode);}
        else collision(e.qualification,e.artifact.foreign,e.artifact.staged,candidateRule,whole.source,candidate,fact,denys);
    }
    static void heads(ContextUniversalCandidate.Evaluation e,boolean leading,boolean negative,Entry rule,String fact,List<String> denys,int mode){
        if(mode==6){require(e.qualification.certificate.input.products.stream().noneMatch(row->row.clause.literals.size()==1&&row.clause.literals.get(0).predicate.equals("out")&&row.clause.literals.get(0).positive!=negative),"no proved output without producer");if(e.artifact.staged.primary.contains(rule)){Set<Source> support=new HashSet<>();support.add(rule.source);e.artifact.foreign.stream().flatMap(f->f.primary.stream()).filter(f->denys.contains(f.statement)).forEach(f->support.add(f.source));require(e.qualification.certificate.input.products.stream().anyMatch(row->{if(row.clause.literals.size()!=1||row.clause.variables.size()!=1||!row.support.sources.equals(support))return false;Atom a=row.clause.literals.get(0);int ui=leading?2:0,vi=leading?1:2,xi=leading?0:1;return a.predicate.equals("rel")&&a.positive==negative&&a.arguments.get(xi).variable>=0&&a.arguments.get(ui).variable<0&&a.arguments.get(vi).variable<0&&a.arguments.get(ui).value.semanticallyEquals(e.artifact.foreign.stream().flatMap(f->f.primary.stream()).filter(f->denys.get(0).equals(f.statement)).findFirst().get().clauses.get(0).literals.get(0).arguments.get(1).value)&&a.arguments.get(vi).value.semanticallyEquals(e.artifact.foreign.stream().flatMap(f->f.primary.stream()).filter(f->denys.get(1).equals(f.statement)).findFirst().get().clauses.get(0).literals.get(0).arguments.get(0).value);}),"two independent Denies yield exact counter-relation fibre with both Sources");}return;}
        Entry producer=e.artifact.staged.primary.stream().filter(v->v.statement.equals(fact)).findFirst().get();Atom input=producer.clauses.get(0).literals.get(0);SemanticTermSnapshot u=input.arguments.get(leading?2:0).value,v=input.arguments.get(leading?1:2).value;Set<Source> base=new HashSet<>(Arrays.asList(rule.source,producer.source));
        if(mode==0||mode==3||mode==4){require(e.qualification.certificate.input.products.stream().anyMatch(row->row.clause.literals.size()==2&&row.clause.variables.isEmpty()&&row.support.sources.equals(base)&&row.clause.literals.stream().allMatch(a->a.predicate.equals("out")&&a.positive!=negative&&a.arguments.size()==2&&a.arguments.get(1).value.semanticallyEquals(u))&&row.clause.literals.stream().anyMatch(a->a.arguments.get(0).value.semanticallyEquals(u))&&row.clause.literals.stream().anyMatch(a->a.arguments.get(0).value.semanticallyEquals(v))),"whole residual disjunction with exact rule+producer support");require(e.qualification.certificate.input.products.stream().noneMatch(row->row.clause.literals.size()==1&&row.clause.literals.get(0).predicate.equals("out")&&row.clause.literals.get(0).positive!=negative),"neither alternative becomes knowledge without selector");return;}
        boolean diagonal=mode==2||mode==7;Set<Source> support=new HashSet<>(base);if(mode!=7)e.artifact.foreign.stream().flatMap(f->f.primary.stream()).filter(f->denys.contains(f.statement)).forEach(f->support.add(f.source));SemanticTermSnapshot first=diagonal?u:v;
        require(e.qualification.certificate.input.products.stream().anyMatch(row->{if(row.clause.literals.size()!=1||!row.clause.variables.isEmpty()||!row.support.sources.equals(support))return false;Atom a=row.clause.literals.get(0);return a.predicate.equals("out")&&a.positive!=negative&&a.arguments.get(0).value.semanticallyEquals(first)&&a.arguments.get(1).value.semanticallyEquals(u);}),"selected or factored ground unit retains exact necessary whole Sources");require(e.qualification.certificate.input.products.stream().filter(row->row.clause.literals.size()==1&&row.clause.literals.get(0).predicate.equals("out")&&row.clause.literals.get(0).positive!=negative).allMatch(row->{Atom a=row.clause.literals.get(0);return row.clause.variables.isEmpty()&&a.arguments.get(0).value.semanticallyEquals(first)&&a.arguments.get(1).value.semanticallyEquals(u);}),"no denied or unrelated alternative exported as proved output");
    }
    static void collision(ContextUniversalFamilyInspection.Result r,List<Snapshot> foreign,Snapshot staged,boolean candidateRule,Source rule,String candidate,String fact,List<String> denys){
        require(r.status==Status.COLLISION&&r.certificate==null&&r.collision!=null&&!r.collision.oppositions.isEmpty(),"complete disjunctive contradiction");Set<Source> expectedForeign=new HashSet<>();for(Snapshot f:foreign)for(Entry e:f.primary)if(denys.contains(e.statement))expectedForeign.add(e.source);if(!candidateRule)expectedForeign.add(rule);Set<Source> expectedLocal=new HashSet<>();if(staged!=null)for(Entry e:staged.primary)if(e.statement.equals(candidate)||(candidateRule&&e.statement.equals(fact)))expectedLocal.add(e.source);
        for(ContextUniversalUnitProof.Proof p:r.collision.oppositions){Set<Source> local=new HashSet<>(),other=new HashSet<>();for(Source v:p.support.sources)(v.localX?local:other).add(v);require(p.dependsOnX&&p.contradiction&&p.conclusion==null&&p.support.sources.size()==2+denys.size()&&local.size()==(candidateRule?2:1)&&other.equals(expectedForeign),"all and only necessary whole rule/producer/Denies");if(staged!=null)require(local.equals(expectedLocal),"exact local whole identities");}
    }
    static void one(boolean leading,boolean negative,boolean reverse,boolean nativePath,boolean candidateRule,int mode)throws Exception{
        Path dir=Files.createTempDirectory("disjunctive-outer-write-");System.setProperty("user.home",dir.toString());String s=negative?"~":"",op=negative?"":"~",rule="!@u @v ($x "+s+"rel("+(leading?"x,v,u":"u,x,v")+"))->("+s+"out(u,u)||"+s+"out(v,u));",fact="!"+s+"rel("+(mode>=7?(leading?"9,1,1":"1,9,1"):(leading?"9,2,1":"1,9,2"))+");",da=mode==1||mode==5||mode==6||mode==8?"!"+op+"out(1,1);":mode==3?"!"+op+"out(1,2);":mode==4?"!"+op+"out(2,2);":"!denyAMarker(2);",db=mode==2||mode==5||mode==6?"!"+op+"out(2,1);":"!denyBMarker(2);",candidate=candidateRule?rule:mode==6?"!safe(1);":fact;boolean safe=mode!=5&&mode!=8;List<String> denys=new ArrayList<>();if(!da.contains("Marker"))denys.add(da);if(!db.contains("Marker"))denys.add(db);
        ContextSevenPremiseNativeWriteRunner.create(dir,"Bridge",candidateRule?"!bridgeMarker(2);":rule);ContextSevenPremiseNativeWriteRunner.create(dir,"DenyA",da);ContextSevenPremiseNativeWriteRunner.create(dir,"DenyB",db);ContextSevenPremiseNativeWriteRunner.create(dir,"Other","!other(2);");Set<String> settled;List<RevisionRef> pins;long afterRevision;
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,"X")){
            require(f.root.compile("!base(2);"+(candidateRule&&mode!=6?" "+fact:""),null,false),"only selected original relation fact");for(String name:reverse?new String[]{"Other","DenyB","DenyA","Bridge"}:new String[]{"Bridge","DenyA","DenyB","Other"})f.db.connectContext(name);f.db.saveConnections(f.root);
            ContextProductionInventory before=ContextSevenPremiseNativeWriteRunner.inventory(f);Set<String> origins=ContextSevenPremiseNativeWriteRunner.origins(before);long revision=f.db.getRevision();int rules=f.root.getRules().size();pins=ContextSevenPremiseNativeWriteRunner.pins(f);List<String> foreignPrints;
            try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(f.db,f.root,1000)){foreignPrints=ContextForeignAntecedentQuantifier.fingerprints(lease.inventory());require(lease.bind(WORK,500000).foreign.size()==4,"every private cut bound");}
            ContextUniversalCandidate.Evaluation diagnostic=f.db.qualifyUniversalProductionCandidate(f.root,candidate,1000,16,16,16,65536,1000000,WORK,500000,WORK);verdict(diagnostic,leading,negative,candidateRule,mode,rule,candidate,fact,denys);require(f.db.getRevision()==revision&&ContextSevenPremiseNativeWriteRunner.inventory(f).fingerprint.equals(before.fingerprint),"diagnostic preserves exact physical source");
            if(nativePath){ContextPendingNativeWrite attempt=f.db.beginUniversalWrite(f.root,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK);try{ContextProductionCommitException failure=null;try{f.root.query(candidate,null,false);}catch(ContextProductionCommitException caught){failure=caught;}if(safe)require(failure==null,"actual native diagonal-outer-parameter safe publication");else{require(failure!=null&&failure.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT&&failure.getFamilyAudit()!=null&&failure.getFamilyAudit().verified&&failure.getFamilyAudit().verdict!=diagnostic.qualification,"actual native diagonal-head conflict freshly audited");collision(failure.getFamilyAudit().verdict,diagnostic.artifact.foreign,null,candidateRule,diagnostic.artifact.foreign.stream().flatMap(v->v.primary.stream()).filter(v->v.statement.equals(rule)).findFirst().map(v->v.source).orElse(null),candidate,fact,denys);}}finally{f.db.endNativeWrite(attempt);}}
            else{DB.UniversalProductionWriteResult result=f.db.writeUniversalProductionCandidate(f.root,candidate,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK,false);require(result.status==(safe?DB.ProductionWriteStatus.PUBLISHED:DB.ProductionWriteStatus.COLLISION)&&result.trial!=diagnostic&&result.audit!=null&&result.audit.verified&&result.audit.evaluation==result.trial,"fresh exact public trial/audit governs diagonal-outer-parameter verdict");verdict(result.trial,leading,negative,candidateRule,mode,rule,candidate,fact,denys);require(result.before.getRevision()==revision&&result.after.getRevision()==f.db.getRevision(),"actual public physical references");}
            ContextProductionInventory after=ContextSevenPremiseNativeWriteRunner.inventory(f);settled=ContextSevenPremiseNativeWriteRunner.origins(after);afterRevision=f.db.getRevision();Set<String> expected=new HashSet<>(origins);if(safe)expected.add(candidate);require(settled.equals(expected)&&after.primary.size()==expected.size()&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"only whole proposed Source publishes; no foreign/derived primary import");if(safe)require(afterRevision>revision,"safe publication advances physical revision");else require(afterRevision==revision&&f.root.getRules().size()==rules&&after.fingerprint.equals(before.fingerprint),"conflict preserves exact revision/rules/fingerprint");try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(f.db,f.root,1000)){require(ContextForeignAntecedentQuantifier.fingerprints(lease.inventory()).equals(foreignPrints),"all initialized foreign inventories unchanged");}
        }
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,"X")){require(f.db.getRevision()>=afterRevision&&ContextSevenPremiseNativeWriteRunner.origins(ContextSevenPremiseNativeWriteRunner.inventory(f)).equals(settled)&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"ordinary durable reopen retains exact settled whole origins and pins");try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(f.db,f.root,1000)){require(lease.bind(WORK,500000).foreign.size()==4,"all private cuts bind after reopen");}}
    }
    static void run(boolean leading,boolean negative,String marker){try{for(boolean r:new boolean[]{false,true})for(boolean p:new boolean[]{false,true})for(boolean c:new boolean[]{false,true})for(int m=0;m<9;m++)one(leading,negative,r,p,c,m);System.out.println(marker+" checks="+(checks+ContextSevenPremiseNativeWriteRunner.checks));System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
